"""Jalur JavaScript bagian 3: perulangan, kontrol alur, exception, operator, fungsi, strict mode, this."""
from rb_js import J, JT, SX, SN
from mobile_lib import M, q

JS3 = [
M('Perulangan dan iterasi', 'Pemula',
  'for, while, do...while, for...in, for...of, serta break, continue, dan label.',
  ['Loops and Iterations', 'for statement', 'while loop', 'do...while', 'for...in loop', 'for...of loop', 'break / continue'], [
  J('for, while, dan do...while',
    ['<code>for (awal; kondisi; langkah)</code> cocok saat jumlah putaran diketahui. <code>while (kondisi)</code> mengulang selama kondisi true dan diperiksa <b>sebelum</b> setiap putaran, cocok saat jumlah putaran belum diketahui (misalnya membaca data sampai habis). <code>do { } while (kondisi)</code> memeriksa <b>setelah</b> putaran sehingga isinya pasti berjalan minimal sekali, cocok untuk "coba dulu lalu ulangi jika gagal".',
     'Hati-hati dengan <b>infinite loop</b>: kondisi yang tidak pernah false akan membekukan tab browser karena JS single-threaded. Pastikan variabel kondisi berubah di setiap putaran, dan beri batas maksimum untuk loop percobaan ulang.',
     'Penghitung <code>let</code> di <code>for</code> dibuat baru di setiap putaran, sehingga callback di dalam loop menangkap nilai yang benar. Dengan <code>var</code>, semua callback berbagi satu variabel (bug klasik yang dibahas di modul closure).'],
    "// for: jumlah putaran pasti\nlet total = 0;\nfor (let i = 1; i <= 5; i++) total += i;\nconsole.log('1+2+3+4+5 =', total);\n\n// while: tabungan sampai target\nlet saldo = 1_000_000, bulan = 0;\nwhile (saldo < 1_500_000) {\n  saldo += 150_000;\n  bulan++;\n}\nconsole.log(`target tercapai di bulan ke-${bulan}, saldo ${saldo}`);\n\n// do...while: percobaan ulang dengan batas\nconst hasilAcak = [false, false, true];   // simulasi: sukses di percobaan ke-3\nlet percobaan = 0, sukses;\ndo {\n  sukses = hasilAcak[percobaan];\n  percobaan++;\n  console.log(`percobaan ${percobaan}: ${sukses ? 'berhasil' : 'gagal'}`);\n} while (!sukses && percobaan < 5);\n\n// mundur dan langkah 2\nconst hitung = [];\nfor (let i = 10; i > 0; i -= 3) hitung.push(i);\nconsole.log(hitung);",
    tb=[{'c': 'Memilih jenis loop', 'h': ['Loop', 'Kondisi diperiksa', 'Pakai saat'], 'r': [
      ['for', 'Sebelum putaran', 'Jumlah putaran/indeks diketahui'], ['while', 'Sebelum putaran', 'Ulang sampai kondisi berubah'], ['do...while', 'Setelah putaran', 'Minimal sekali jalan (retry, menu)'],
      ['for...of', 'Per elemen iterable', 'Nilai array, string, Map, Set'], ['for...in', 'Per key enumerable', 'Key object (jarang)'], ['arr.forEach', 'Per elemen', 'Efek samping sederhana (tidak bisa break)']]}],
    pts=['for untuk jumlah pasti, while untuk kondisi, do...while minimal sekali.', 'Hindari infinite loop: kondisi harus berubah.', 'let di for membuat binding baru per putaran.', 'Pemisah angka 1_000_000 memudahkan membaca.'],
    qs=[q('Berapa kali isi do { } while (false) dijalankan?', ['1 kali', '0 kali', 'Tak terhingga'], 0, 'Kondisi diperiksa setelah putaran pertama.'),
        q('Hasil let n = 0; while (n < 3) n++; console.log(n)?', ['3', '2', '4'], 0, 'Berhenti saat n = 3.')],
    so=[SX('Cetak tabel perkalian 7 dari 1 sampai 10 dengan format "7 x 3 = 21".', 'for dari 1 sampai 10.',
           "for (let i = 1; i <= 10; i++) {\n  console.log(`7 x ${String(i).padStart(2)} = ${7 * i}`);\n}"),
        SX('Pinjaman Rp5.000.000 dicicil Rp750.000 per bulan. Dengan while, hitung berapa bulan sampai lunas dan berapa cicilan terakhir.', 'Kurangi sisa selama sisa > 0; cicilan terakhir = min(sisa, 750000).',
           "let sisa = 5_000_000, bulan = 0, terakhir = 0;\nwhile (sisa > 0) {\n  terakhir = Math.min(sisa, 750_000);\n  sisa -= terakhir;\n  bulan++;\n}\nconsole.log(`lunas dalam ${bulan} bulan, cicilan terakhir ${terakhir}`);")]),
  J('for...in dan for...of',
    ['<code>for...of</code> mengiterasi <b>nilai</b> dari objek <b>iterable</b>: array, string (per karakter Unicode, aman untuk emoji), Map, Set, arguments, NodeList, dan generator. Ini pilihan utama untuk array. Butuh indeks? Pakai <code>arr.entries()</code> dengan destructuring.',
     '<code>for...in</code> mengiterasi <b>key string enumerable</b> sebuah object, <b>termasuk yang diwarisi</b> dari prototype. Untuk object biasa, gaya modern lebih memilih <code>Object.keys</code>, <code>Object.values</code>, atau <code>Object.entries</code> dengan for...of karena hanya mengambil properti milik sendiri. Jangan pakai for...in untuk array: key-nya string dan urutan atau properti tambahan bisa mengejutkan.',
     'Object biasa <b>bukan iterable</b>, sehingga <code>for (const x of obj)</code> melempar TypeError. Urutan key object: key berbentuk bilangan bulat diurutkan naik lebih dulu, lalu key string sesuai urutan sisip.'],
    "const nilai = [90, 75, 88];\nfor (const n of nilai) console.log('nilai', n);\nfor (const [i, n] of nilai.entries()) console.log(`#${i + 1}: ${n}`);\n\nfor (const ch of 'Hi😀') console.log(ch);           // per karakter, emoji utuh\nconsole.log('Hi😀'.length, [...'Hi😀'].length);\n\nconst produk = { nama: 'Sambal', harga: 18000, stok: 40 };\nfor (const key in produk) console.log(key, '=', produk[key]);\nfor (const [k, v] of Object.entries(produk)) console.log(`${k}: ${v}`);\n\nconst induk = { warisan: true };\nconst anak = Object.create(induk);\nanak.milikSendiri = 1;\nconst dariForIn = [];\nfor (const k in anak) dariForIn.push(k);\nconsole.log(dariForIn, Object.keys(anak));\nconsole.log(Object.keys({ b: 1, 2: 'x', a: 2, 1: 'y' }));\ntry {\n  for (const x of produk) console.log(x);\n} catch (e) { console.log(e.name + ':', e.message); }",
    tb=[{'c': 'for...in vs for...of', 'h': ['Aspek', 'for...in', 'for...of'], 'r': [
      ['Mengambil', 'Key (string)', 'Nilai'], ['Bekerja pada', 'Object apa saja', 'Iterable (array, string, Map, Set)'], ['Properti warisan', 'Ikut', 'Tidak relevan'],
      ['Untuk array', 'Tidak dianjurkan', 'Dianjurkan'], ['Untuk object biasa', 'Bisa (hati-hati warisan)', 'TypeError; pakai Object.entries'], ['Bisa break/continue', 'Ya', 'Ya']]}],
    pts=['for...of untuk nilai iterable; for...in untuk key object.', 'for...in ikut properti warisan.', 'Object.entries + for...of untuk object.', 'Object biasa bukan iterable.'],
    qs=[q('Output for (const i in ["a","b"]) console.log(typeof i)?', ['"string" dua kali', '"number" dua kali', 'TypeError'], 0, 'Key array dibaca sebagai string.'),
        q('Cara mendapatkan indeks dan nilai di for...of?', ['for (const [i, v] of arr.entries())', 'for (const i, v of arr)', 'for (const v in arr)'], 0, 'entries menghasilkan pasangan [indeks, nilai].')],
    so=[SX('Object stok <code>{kopi: 3, teh: 0, gula: 12, susu: 0}</code>: cetak barang yang habis memakai Object.entries dan for...of.', 'Destructuring [barang, jumlah] lalu cek jumlah === 0.',
           "const stok = { kopi: 3, teh: 0, gula: 12, susu: 0 };\nfor (const [barang, jumlah] of Object.entries(stok)) {\n  if (jumlah === 0) console.log(`${barang} habis`);\n}")]),
  J('break, continue, dan label',
    ['<code>break</code> menghentikan loop (atau switch) terdekat seketika. <code>continue</code> melompati sisa putaran saat ini dan lanjut ke putaran berikutnya. Keduanya membuat kode lebih efisien, misalnya berhenti mencari begitu data ditemukan.',
     'Untuk loop bersarang, <b>label</b> (<code>luar:</code> sebelum loop) memungkinkan <code>break luar</code> atau <code>continue luar</code> menargetkan loop luar. Fitur ini jarang dipakai; sering kali lebih bersih memindahkan loop ke fungsi dan memakai <code>return</code>.',
     '<code>forEach</code>, <code>map</code>, dan metode callback lain <b>tidak bisa di-break</b>; <code>return</code> di dalam callback hanya melompati satu item. Jika butuh berhenti lebih awal, pakai for...of, atau <code>some</code>/<code>find</code> yang berhenti saat callback mengembalikan true.'],
    "const transaksi = [120, -1, 300, 0, 450, 999, 80];\nlet total = 0;\nfor (const t of transaksi) {\n  if (t === 999) { console.log('penanda akhir, berhenti'); break; }\n  if (t <= 0) { console.log('lewati nilai tidak valid:', t); continue; }\n  total += t;\n}\nconsole.log('total valid:', total);\n\n// label untuk keluar dari dua loop sekaligus\nconst kursi = [['A1', 'A2'], ['B1', 'B2'], ['C1', 'C2']];\nconst terisi = new Set(['A1', 'A2', 'B1']);\nlet dapat = null;\ncari: for (const baris of kursi) {\n  for (const k of baris) {\n    if (!terisi.has(k)) { dapat = k; break cari; }\n  }\n}\nconsole.log('kursi kosong pertama:', dapat);\n\n// some berhenti di elemen pertama yang cocok\nlet diperiksa = 0;\nconst adaBesar = transaksi.some(t => { diperiksa++; return t > 400; });\nconsole.log(adaBesar, 'diperiksa:', diperiksa);",
    pts=['break keluar dari loop; continue lompat ke putaran berikutnya.', 'Label untuk loop bersarang (jarang).', 'forEach tidak bisa di-break: pakai for...of, some, atau find.'],
    qs=[q('Output: for (let i=0;i<5;i++){ if(i===2) continue; if(i===4) break; console.log(i) }', ['0 1 3', '0 1 2 3', '0 1'], 0, '2 dilewati, berhenti di 4.'),
        q('Cara menghentikan iterasi lebih awal pada array?', ['for...of dengan break atau arr.some', 'return di forEach', 'break di dalam map'], 0, 'forEach tidak bisa dihentikan.')],
    so=[SX('Cari bilangan prima pertama yang lebih besar dari 90 dengan while dan break; untuk cek prima pakai for dengan continue/break.', 'Uji pembagi dari 2 sampai akar n.',
           "let n = 91;\nwhile (true) {\n  let prima = n > 1;\n  for (let d = 2; d * d <= n; d++) {\n    if (n % d === 0) { prima = false; break; }\n  }\n  if (prima) break;\n  n++;\n}\nconsole.log('prima pertama > 90:', n);")]),
]),

M('Kontrol alur dan exception handling', 'Pemula',
  'if...else, switch, conditional statements, serta throw, try/catch/finally, dan Error objects.',
  ['Control Flow', 'Conditional Statements', 'if...else', 'switch', 'Exception Handling', 'throw statement', 'try / catch / finally', 'Error Objects'], [
  J('if...else dan switch',
    ['<code>if (kondisi) { } else if (...) { } else { }</code> memilih cabang berdasarkan kondisi yang dikonversi ke boolean (truthy/falsy). Untuk kode yang mudah dibaca, pakai <b>guard clause</b> atau <b>early return</b>: tangani kasus khusus di awal fungsi lalu <code>return</code>, sehingga tidak ada if bersarang dalam.',
     '<code>switch (nilai)</code> membandingkan dengan <code>case</code> memakai <b>===</b>. Tanpa <code>break</code>, eksekusi "jatuh" ke case berikutnya (<b>fall-through</b>), yang berguna untuk mengelompokkan beberapa case tetapi sering menjadi bug jika tidak disengaja. Bungkus isi case dengan kurung kurawal jika mendeklarasikan let/const.',
     'Alternatif yang populer: <b>object lookup</b> (peta dari nilai ke hasil) yang lebih ringkas daripada switch panjang, dan operator ternary untuk pilihan dua nilai yang sederhana.'],
    "function ongkir(berat, kota) {\n  if (berat <= 0) return 'berat tidak valid';     // guard clause\n  if (berat > 30) return 'gunakan kargo';\n  let tarif;\n  if (kota === 'Jakarta') tarif = 9000;\n  else if (kota === 'Bandung' || kota === 'Bogor') tarif = 11000;\n  else tarif = 18000;\n  return Math.ceil(berat) * tarif;\n}\nconsole.log(ongkir(1.2, 'Jakarta'), ongkir(3, 'Bogor'), ongkir(2, 'Ambon'), ongkir(0, 'Jakarta'));\n\nfunction namaHari(i) {\n  switch (i) {\n    case 0: return 'Minggu';\n    case 6: return 'Sabtu';\n    case 1: case 2: case 3: case 4: case 5: return 'Hari kerja';   // fall-through disengaja\n    default: return 'tidak dikenal';\n  }\n}\nconsole.log([0, 3, 6, 9].map(namaHari));\n\nswitch ('1') { case 1: console.log('number'); break; default: console.log(\"switch memakai ===, '1' bukan 1\"); }\n\nconst ikonStatus = { lunas: '✅', menunggu: '⏳', batal: '❌' };   // object lookup\nfor (const s of ['lunas', 'batal', 'refund']) console.log(s, ikonStatus[s] ?? '❔');",
    tb=[{'c': 'Pilihan percabangan', 'h': ['Bentuk', 'Cocok untuk'], 'r': [
      ['if / else if / else', 'Kondisi rentang atau logika kompleks'], ['Guard clause + return', 'Validasi di awal fungsi'], ['switch', 'Banyak nilai diskret, perlu fall-through'],
      ['Object/Map lookup', 'Pemetaan nilai ke hasil atau fungsi'], ['Ternary a ? b : c', 'Memilih satu dari dua nilai'], ['&& dan ??', 'Render bersyarat, nilai bawaan']]}],
    pts=['Guard clause mengurangi if bersarang.', 'switch memakai === dan perlu break.', 'Fall-through boleh jika disengaja dan diberi komentar.', 'Object lookup sebagai pengganti switch panjang.'],
    qs=[q("switch ('2') { case 2: ... } masuk ke case 2?", ['Tidak, switch memakai ===', 'Ya, karena koersi', 'Error'], 0, "'2' !== 2."),
        q('Apa akibat lupa break di case?', ['Eksekusi lanjut ke case berikutnya', 'SyntaxError', 'Loop tak terhingga'], 0, 'Fall-through.')],
    so=[SX('Tulis fungsi <code>predikat(nilai)</code>: A (&gt;= 85), B (&gt;= 70), C (&gt;= 55), D (&gt;= 40), E selain itu; nilai di luar 0 sampai 100 menghasilkan "tidak valid". Uji dengan 92, 70, 41, 12, 105.', 'Guard clause untuk validasi, lalu if berurutan dari terbesar.',
           "function predikat(n) {\n  if (n < 0 || n > 100) return 'tidak valid';\n  if (n >= 85) return 'A';\n  if (n >= 70) return 'B';\n  if (n >= 55) return 'C';\n  if (n >= 40) return 'D';\n  return 'E';\n}\nfor (const n of [92, 70, 41, 12, 105]) console.log(n, predikat(n));")]),
  J('throw, try, catch, finally',
    ['Saat terjadi kesalahan yang tidak bisa ditangani di tempat, <code>throw</code> menghentikan eksekusi dan melempar nilai ke atas tumpukan pemanggil sampai ditangkap <code>catch</code>. Jika tidak ada yang menangkap, program berhenti (di Node) atau error muncul di konsol (di browser).',
     '<code>try { }</code> berisi kode yang mungkin gagal, <code>catch (e) { }</code> menanganinya, dan <code>finally { }</code> <b>selalu</b> dijalankan, baik sukses maupun gagal, bahkan setelah <code>return</code>. Finally cocok untuk membersihkan sumber daya: menutup koneksi, mematikan spinner loading, melepas kunci.',
     'Praktik profesional: selalu <code>throw new Error(...)</code> (bukan string) agar ada stack trace; tangkap hanya error yang bisa kamu tangani dan lempar ulang sisanya; jangan menelan error diam-diam dengan catch kosong; dan sertakan <b>cause</b> (<code>new Error(pesan, { cause: e })</code>, ES2022) saat membungkus error agar penyebab asli tidak hilang. Parameter catch boleh dihilangkan (<code>catch { }</code>) jika tidak dipakai.'],
    "function bagi(a, b) {\n  if (b === 0) throw new RangeError('pembagi tidak boleh nol');\n  return a / b;\n}\n\nfunction proses(a, b) {\n  console.log(`mulai ${a}/${b}`);\n  try {\n    return `hasil ${bagi(a, b)}`;\n  } catch (e) {\n    return `gagal: ${e.message}`;\n  } finally {\n    console.log('  finally: matikan spinner');   // tetap jalan walau ada return\n  }\n}\nconsole.log(proses(10, 4));\nconsole.log(proses(1, 0));\n\nfunction bacaKonfig(teks) {\n  try {\n    return JSON.parse(teks);\n  } catch (e) {\n    throw new Error('konfigurasi rusak', { cause: e });   // bungkus dengan cause\n  }\n}\ntry {\n  bacaKonfig('{port: 80}');\n} catch (e) {\n  console.log(e.message, '<-', e.cause.name);\n}",
    tb=[{'c': 'Alur try/catch/finally', 'h': ['Kejadian di try', 'catch jalan?', 'finally jalan?'], 'r': [
      ['Sukses', 'Tidak', 'Ya'], ['Error dilempar', 'Ya', 'Ya, setelah catch'], ['return di try', 'Tidak', 'Ya, sebelum nilai dikembalikan'],
      ['Error di catch', '-', 'Ya, lalu error baru diteruskan'], ['Error asinkron tanpa await', 'Tidak tertangkap', 'Ya (terlalu cepat)']]}],
    pts=['throw new Error(...) agar ada stack trace.', 'finally selalu jalan, cocok untuk cleanup.', 'Jangan menelan error dengan catch kosong.', 'Bungkus error dengan { cause } untuk konteks.'],
    qs=[q('Kapan blok finally dijalankan?', ['Selalu, sukses maupun gagal', 'Hanya jika ada error', 'Hanya jika tidak ada error'], 0, 'Termasuk saat try melakukan return.'),
        q('Kenapa lebih baik throw new Error("x") daripada throw "x"?', ['Error membawa stack trace dan name', 'String lebih lambat', 'throw string adalah SyntaxError'], 0, 'Stack trace penting untuk debugging.')],
    so=[SX('Tulis <code>ambilUmur(teks)</code> yang mengubah teks ke number dan melempar TypeError jika bukan angka, serta RangeError jika di luar 0 sampai 120. Panggil untuk "25", "abc", "150" dan cetak nama error atau hasilnya.', 'Number(teks), cek Number.isNaN, lalu rentang.',
           "function ambilUmur(teks) {\n  const n = Number(teks);\n  if (teks.trim() === '' || Number.isNaN(n)) throw new TypeError(`'${teks}' bukan angka`);\n  if (n < 0 || n > 120) throw new RangeError(`umur ${n} di luar rentang`);\n  return n;\n}\nfor (const t of ['25', 'abc', '150']) {\n  try {\n    console.log('umur:', ambilUmur(t));\n  } catch (e) {\n    console.log(`${e.name}: ${e.message}`);\n  }\n}")]),
  J('Error objects dan custom error',
    ['Semua error bawaan turunan dari <code>Error</code> dan punya <code>name</code>, <code>message</code>, <code>stack</code>, serta opsional <code>cause</code>. Tipe bawaan: <code>SyntaxError</code> (kode atau JSON tidak valid), <code>ReferenceError</code> (nama tidak dikenal, TDZ), <code>TypeError</code> (operasi pada tipe yang salah, misal memanggil undefined), <code>RangeError</code> (nilai di luar rentang), <code>URIError</code>, <code>EvalError</code>, dan <code>AggregateError</code> (banyak error sekaligus, dari Promise.any).',
     'Untuk aplikasi nyata, buat <b>custom error class</b> dengan <code>class ValidasiError extends Error</code>, set <code>this.name</code>, dan tambahkan data (field yang salah, kode HTTP). Penanganannya kemudian memakai <code>instanceof</code> untuk membedakan error yang diharapkan (validasi, 404) dari bug tak terduga.',
     'Di produksi, error yang tidak tertangkap dicatat oleh layanan <b>error monitoring</b> seperti Sentry. Di browser ada event <code>window.onerror</code> dan <code>unhandledrejection</code>; di Node ada <code>process.on("uncaughtException")</code>. Pesan error untuk pengguna harus ramah, sementara detail teknis hanya ke log.'],
    "class ValidasiError extends Error {\n  constructor(field, pesan) {\n    super(pesan);\n    this.name = 'ValidasiError';\n    this.field = field;\n  }\n}\nclass TidakDitemukanError extends Error {\n  name = 'TidakDitemukanError';\n  status = 404;\n}\n\nfunction daftar(user) {\n  if (!user.email?.includes('@')) throw new ValidasiError('email', 'Format email salah');\n  if (user.email === 'ada@contoh.id') throw new TidakDitemukanError('Paket tidak ditemukan');\n  return 'terdaftar';\n}\n\nfor (const u of [{ email: 'rina@contoh.id' }, { email: 'rina' }, { email: 'ada@contoh.id' }, null]) {\n  try {\n    console.log(daftar(u));\n  } catch (e) {\n    if (e instanceof ValidasiError) console.log(`[400] ${e.field}: ${e.message}`);\n    else if (e instanceof TidakDitemukanError) console.log(`[${e.status}] ${e.message}`);\n    else console.log(`[500] bug: ${e.name} - ${e.message}`);\n  }\n}\nconst e = new ValidasiError('nama', 'wajib');\nconsole.log(e instanceof Error, e.stack.split('\\n')[0]);\n\nfor (const kode of ['null.x', 'x.y.z', 'new Array(-1)', '[].reduce((a,b)=>a)']) {\n  try { new Function(kode)(); } catch (err) { console.log(kode.padEnd(20), err.name); }\n}",
    tb=[{'c': 'Tipe error bawaan', 'h': ['Error', 'Penyebab umum', 'Contoh'], 'r': [
      ['SyntaxError', 'Kode atau JSON tidak valid', "JSON.parse('{a:1}')"], ['ReferenceError', 'Nama tidak ada atau di TDZ', 'console.log(belumAda)'],
      ['TypeError', 'Operasi pada tipe yang salah', 'undefined.nama, null()'], ['RangeError', 'Nilai di luar rentang', 'new Array(-1), toFixed(200)'],
      ['URIError', 'URI tidak valid', "decodeURIComponent('%')"], ['AggregateError', 'Kumpulan beberapa error', 'Promise.any semua gagal']]}],
    pts=['Error punya name, message, stack, cause.', 'TypeError dan ReferenceError paling sering ditemui.', 'Custom error dengan extends Error + instanceof.', 'Error monitoring (Sentry) untuk produksi.'],
    qs=[q('Error yang muncul saat mengakses properti dari undefined?', ['TypeError', 'ReferenceError', 'RangeError'], 0, 'Membaca properti dari undefined adalah operasi pada tipe yang salah.'),
        q('Cara membedakan jenis custom error di catch?', ['e instanceof NamaError', 'typeof e', 'e === NamaError'], 0, 'instanceof memeriksa rantai prototype.')]),
]),

M('Ekspresi dan operator', 'Pemula',
  'Operator assignment, perbandingan, aritmetika, logika, string, kondisional, koma, unary, bitwise, BigInt, destructuring, spread, dan presedensi.',
  ['Expressions and Operators', 'Assignment Operators', 'Comparison Operators', 'Arithmetic Operators', 'Logical Operators', 'String Operators', 'Conditional Operators', 'Comma Operators', 'Unary Operators', 'Bitwise Operators', 'BigInt Operators'], [
  J('Aritmetika, assignment, dan perbandingan',
    ['<b>Aritmetika</b>: <code>+ - * /</code>, <code>%</code> (sisa bagi, tandanya mengikuti operand kiri), <code>**</code> (pangkat), <code>++</code> dan <code>--</code>. Bentuk prefix <code>++i</code> menaikkan lalu mengembalikan nilai baru; postfix <code>i++</code> mengembalikan nilai lama lalu menaikkan.',
     '<b>Assignment</b>: <code>=</code> dan bentuk gabungannya <code>+= -= *= /= %= **=</code>, operator bitwise <code>&lt;&lt;= &gt;&gt;= &= |= ^=</code>, serta <b>logical assignment</b> ES2021: <code>a ||= b</code> (isi jika falsy), <code>a &&= b</code> (isi jika truthy), <code>a ??= b</code> (isi jika null/undefined).',
     '<b>Perbandingan</b>: <code>&lt; &gt; &lt;= &gt;=</code>, <code>=== !==</code>, <code>== !=</code>. Dua string dibandingkan per kode karakter (huruf besar lebih kecil dari huruf kecil), jadi untuk mengurutkan nama pakai <code>localeCompare</code> atau <code>Intl.Collator</code>.'],
    "console.log(17 % 5, -17 % 5, 2 ** 10, 7 / 2, Math.trunc(7 / 2));\nlet i = 5;\nconsole.log(i++, i, ++i, i);          // postfix vs prefix\n\nlet poin = 100;\npoin += 50; poin *= 2; poin -= 25; poin **= 1;\nconsole.log('poin:', poin);\n\nconst opsi = { tema: '', bahasa: null, notif: true };\nopsi.tema ||= 'terang';    // '' falsy -> diisi\nopsi.bahasa ??= 'id';      // null -> diisi\nopsi.notif &&= 'email';    // truthy -> diganti\nconsole.log(opsi);\n\nconsole.log('apel' < 'jeruk', 'Zebra' < 'apel', 'a'.charCodeAt(0), 'Z'.charCodeAt(0));\nconst nama = ['citra', 'Ani', 'budi', 'Dodi', 'Émile'];\nconsole.log(nama.toSorted(), nama.toSorted((a, b) => a.localeCompare(b, 'id')));",
    tb=[{'c': 'Logical assignment (ES2021)', 'h': ['Operator', 'Sama dengan', 'Mengisi saat a'], 'r': [
      ['a ||= b', 'a || (a = b)', 'falsy (0, "", null, ...)'], ['a &&= b', 'a && (a = b)', 'truthy'], ['a ??= b', 'a ?? (a = b)', 'null atau undefined']]}],
    pts=['% mengikuti tanda operand kiri; ** untuk pangkat.', 'i++ mengembalikan nilai lama, ++i nilai baru.', '||=, &&=, ??= untuk default yang ringkas.', 'localeCompare untuk mengurutkan teks.'],
    qs=[q('let a = 3; const b = a++ + 1; nilai b?', ['4', '5', '3'], 0, 'a++ mengembalikan 3, lalu a menjadi 4.'),
        q('Setelah let x = 0; x ||= 10; x ??= 20; nilai x?', ['10', '20', '0'], 0, '0 falsy sehingga diisi 10; 10 bukan nullish.')]),
  J('Operator logika, kondisional, dan string',
    ['<code>&&</code>, <code>||</code>, dan <code>??</code> tidak selalu mengembalikan boolean; mereka mengembalikan <b>salah satu operand</b> dan melakukan <b>short-circuit</b> (operand kanan tidak dievaluasi jika tidak perlu). <code>a || b</code> = a jika truthy, selain itu b. <code>a && b</code> = a jika falsy, selain itu b. <code>a ?? b</code> = a kecuali a null/undefined. <code>!</code> membalik boolean, <code>!!</code> mengubah ke boolean.',
     '<b>Optional chaining</b> <code>?.</code> menghentikan akses jika nilai di kiri null/undefined dan menghasilkan undefined, termasuk untuk panggilan (<code>fn?.()</code>) dan indeks (<code>arr?.[0]</code>). Gabungan <code>a?.b ?? \'default\'</code> sangat umum untuk data API yang tidak lengkap.',
     '<b>Operator kondisional (ternary)</b> <code>kondisi ? a : b</code> adalah satu-satunya operator dengan tiga operand; cocok untuk memilih nilai, hindari ternary bersarang yang sulit dibaca. <b>Operator string</b>: <code>+</code> dan <code>+=</code> menggabungkan string, tetapi template literal biasanya lebih jelas.'],
    "console.log('a' || 'b', '' || 'b', 0 && 'x', 1 && 'x', null ?? 'def', 0 ?? 'def');\n\nfunction log(pesan) { console.log('  dipanggil:', pesan); return true; }\nconsole.log(false && log('tidak akan jalan'));\nconsole.log(true || log('tidak akan jalan'));\nconsole.log(true && log('jalan'));\n\nconst respons = { data: { user: { nama: 'Bayu', alamat: null } } };\nconsole.log(respons.data?.user?.nama, respons.data?.user?.alamat?.kota ?? 'kota belum diisi');\nconsole.log(respons.meta?.halaman, respons.data.sapa?.(), respons.list?.[0]);\n\nconst stok = 0;\nconst label = stok > 10 ? 'tersedia' : stok > 0 ? 'hampir habis' : 'habis';\nconsole.log(label);\nlet salam = 'Halo';\nsalam += ', ' + 'Bayu';\nconsole.log(salam, `${salam}!`.length);\nconsole.log(!!'teks', !0, !![]);",
    tb=[{'c': 'Nilai kembali operator logika', 'h': ['Ekspresi', 'Hasil', 'Alasan'], 'r': [
      ["'' || 'tamu'", "'tamu'", "'' falsy"], ["0 ?? 5", '0', '0 bukan nullish'], ["user && user.nama", 'null jika user null, selain itu user.nama', 'short-circuit'],
      ["null?.x", 'undefined', 'optional chaining berhenti'], ["a?.b ?? 'x'", "'x' jika a atau a.b nullish", 'kombinasi umum']]}],
    pts=['&&, ||, ?? mengembalikan operand, bukan selalu boolean.', 'Short-circuit: sisi kanan bisa tidak dievaluasi.', '?. untuk data yang mungkin kosong; padukan dengan ??.', 'Ternary untuk memilih nilai, hindari bersarang.'],
    qs=[q("Hasil 0 || 'kosong'?", ["'kosong'", '0', 'false'], 0, '0 falsy.'),
        q("Hasil 0 ?? 'kosong'?", ['0', "'kosong'", 'null'], 0, '?? hanya untuk null/undefined.'),
        q('Hasil user?.profil?.foto jika user undefined?', ['undefined', 'TypeError', 'null'], 0, 'Optional chaining menghentikan akses.')],
    so=[SX('Dari respons API <code>{produk: {nama: "Keripik", diskon: 0, varian: null}}</code>, cetak nama, diskon (0 harus tetap 0), jumlah varian (0 jika null), dan nama penjual (default "Toko Resmi") yang tidak ada di data.', 'Gunakan ?. dan ??, jangan ||.',
           "const res = { produk: { nama: 'Keripik', diskon: 0, varian: null } };\nconsole.log('nama   :', res.produk?.nama);\nconsole.log('diskon :', res.produk?.diskon ?? 10);\nconsole.log('varian :', res.produk?.varian?.length ?? 0);\nconsole.log('penjual:', res.produk?.penjual?.nama ?? 'Toko Resmi');")]),
  J('Unary, koma, bitwise, dan BigInt',
    ['<b>Unary operator</b> bekerja pada satu operand: <code>typeof</code>, <code>delete</code> (hapus properti), <code>void</code> (selalu undefined), <code>+x</code> (ke number), <code>-x</code>, <code>!x</code>, <code>~x</code> (NOT bitwise), <code>++</code>/<code>--</code>, serta <code>await</code>.',
     '<b>Operator koma</b> mengevaluasi beberapa ekspresi dari kiri ke kanan dan mengembalikan yang terakhir. Pemakaian yang wajar hanya di bagian for dengan dua penghitung; di luar itu membuat kode sulit dibaca.',
     '<b>Bitwise</b> (<code>& | ^ ~ &lt;&lt; &gt;&gt; &gt;&gt;&gt;</code>) mengubah operand menjadi bilangan bulat <b>32-bit</b> lalu bekerja per bit. Dipakai untuk <b>flag/izin</b> yang digabung dalam satu angka, warna heksadesimal, hashing, dan grafis. <b>Operator BigInt</b> sama dengan number (<code>+ - * / % **</code>, bitwise kecuali <code>&gt;&gt;&gt;</code>), pembagian dibulatkan ke nol, dan unary <code>+</code> tidak diizinkan.'],
    "const akun = { nama: 'Lia', token: 'rahasia' };\ndelete akun.token;\nconsole.log(akun, typeof akun.token, void 0, -'5', +true);\n\nfor (let i = 0, j = 4; i < j; i++, j--) console.log('pasangan', i, j);   // koma di for\nconst x = (1, 2, 3);\nconsole.log('koma mengembalikan yang terakhir:', x);\n\n// flag izin dengan bitwise\nconst BACA = 1, TULIS = 2, HAPUS = 4;      // 001, 010, 100\nlet izin = BACA | TULIS;                   // gabung\nconsole.log(izin.toString(2).padStart(3, '0'), Boolean(izin & TULIS), Boolean(izin & HAPUS));\nizin |= HAPUS; izin &= ~TULIS;             // tambah HAPUS, cabut TULIS\nconsole.log(izin.toString(2).padStart(3, '0'));\n\nconst warna = 0xff8800;                    // pecah warna hex ke RGB\nconsole.log((warna >> 16) & 255, (warna >> 8) & 255, warna & 255);\nconsole.log(5 ^ 3, ~5, 1 << 10, -16 >> 2, -16 >>> 28, 2 ** 32 | 0);\n\nconsole.log(7n / 2n, -7n / 2n, 2n ** 70n, 6n & 3n, 1n << 64n);\ntry { console.log(+5n); } catch (e) { console.log(e.name + ':', e.message); }\nconsole.log(5n == 5, 5n === 5, 2n > 1, typeof (5n * 2n));",
    tb=[{'c': 'Operator bitwise', 'h': ['Operator', 'Nama', 'Contoh (biner)'], 'r': [
      ['&', 'AND', '101 & 011 = 001'], ['|', 'OR', '101 | 011 = 111'], ['^', 'XOR', '101 ^ 011 = 110'], ['~', 'NOT', '~5 = -6'],
      ['<<', 'Geser kiri', '1 << 3 = 8'], ['>>', 'Geser kanan (jaga tanda)', '-16 >> 2 = -4'], ['>>>', 'Geser kanan tanpa tanda', '-16 >>> 28 = 15']]}],
    pts=['delete menghapus properti; void selalu undefined.', 'Operator koma hanya wajar di for.', 'Bitwise bekerja pada 32-bit; cocok untuk flag dan warna.', 'BigInt: pembagian dibulatkan ke nol, tanpa unary +.'],
    qs=[q('Hasil 6 & 3?', ['2', '7', '5'], 0, '110 & 011 = 010.'),
        q('Hasil 7n / 2n?', ['3n', '3.5', '4n'], 0, 'Pembagian BigInt dibulatkan ke nol.')],
    so=[SX('Ubah warna hex <code>"#1E90FF"</code> menjadi string "rgb(30, 144, 255)" memakai parseInt basis 16 dan operator geser bitwise.', 'n = parseInt(hex.slice(1), 16); r = n >> 16 & 255.',
           "const hex = '#1E90FF';\nconst n = parseInt(hex.slice(1), 16);\nconst r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;\nconsole.log(`rgb(${r}, ${g}, ${b})`);")]),
  J('Destructuring, spread, rest, dan presedensi',
    ['<b>Destructuring</b> membongkar array atau object ke variabel: <code>const [a, b] = arr</code>, <code>const { nama, umur: usia = 17 } = obj</code> (ganti nama dan nilai bawaan), dan bisa bersarang. Sangat umum di parameter fungsi dan React (<code>const [state, setState] = useState()</code>).',
     '<b>Spread</b> <code>...</code> menyebarkan isi iterable atau object: menyalin dan menggabung array (<code>[...a, ...b]</code>), object (<code>{...default, ...opsi}</code>, yang kanan menimpa yang kiri), atau argumen fungsi (<code>Math.max(...arr)</code>). <b>Rest</b> memakai tanda yang sama tetapi <b>mengumpulkan</b> sisa elemen: <code>const [pertama, ...sisa] = arr</code>.',
     '<b>Presedensi</b> menentukan urutan evaluasi: kurung, lalu akses anggota dan panggilan, unary, <code>**</code>, <code>* / %</code>, <code>+ -</code>, perbandingan, kesetaraan, <code>&&</code>, <code>||</code> dan <code>??</code>, ternary, assignment. <code>??</code> tidak boleh dicampur langsung dengan <code>||</code>/<code>&&</code> tanpa kurung (SyntaxError). Jika ragu, beri kurung: kode lebih jelas bagi pembaca.'],
    "const [kota1, , kota3 = 'Medan', ...lain] = ['Bandung', 'Bogor', undefined, 'Solo', 'Palu'];\nconsole.log(kota1, kota3, lain);\n\nconst user = { id: 7, profil: { nama: 'Nia', kota: 'Malang' }, peran: 'admin' };\nconst { profil: { nama, kota }, peran: role = 'user', aktif = true, ...sisa } = user;\nconsole.log(nama, kota, role, aktif, sisa);\n\nlet a = 1, b = 2;\n[a, b] = [b, a];                                   // tukar tanpa variabel sementara\nconsole.log(a, b);\n\nconst bawaan = { tema: 'terang', bahasa: 'id', ukuran: 14 };\nconst pilihan = { tema: 'gelap' };\nconsole.log({ ...bawaan, ...pilihan });            // kanan menimpa kiri\nconst nilai = [70, 98, 85];\nconsole.log(Math.max(...nilai), [...nilai, 60], [...'abc']);\n\nfunction buatPesanan({ produk, jumlah = 1, catatan = '-' }) {   // destructuring parameter\n  return `${jumlah}x ${produk} (${catatan})`;\n}\nconsole.log(buatPesanan({ produk: 'Martabak' }));\n\nconsole.log(2 + 3 * 4 ** 2, (2 + 3) * 4, 1 + 2 + '3', '1' + 2 + 3, !true || true, 1 < 2 < 3, 3 > 2 > 1);\nconsole.log((null || undefined) ?? 'aman pakai kurung');",
    tb=[{'c': 'Presedensi operator (tinggi ke rendah, ringkas)', 'h': ['Tingkat', 'Operator'], 'r': [
      ['1', '( ) pengelompokan'], ['2', '. [] () new ?. (akses, panggil)'], ['3', 'x++ x--'], ['4', '! ~ + - ++x --x typeof void delete await'], ['5', '** (asosiatif kanan)'],
      ['6', '* / %'], ['7', '+ -'], ['8', '<< >> >>>'], ['9', '< > <= >= in instanceof'], ['10', '== != === !=='], ['11', '& lalu ^ lalu |'], ['12', '&&'], ['13', '|| dan ??'], ['14', '? : ternary'], ['15', '= += ... => yield ...'], ['16', ', koma']]}],
    pts=['Destructuring dengan rename, default, dan bersarang.', 'Spread menyebarkan, rest mengumpulkan.', '{...a, ...b}: yang kanan menimpa.', 'Beri kurung saat ragu; ?? wajib kurung bila dicampur || atau &&.'],
    qs=[q('Hasil 3 > 2 > 1?', ['false', 'true', 'TypeError'], 0, '3 > 2 = true, lalu true > 1 berarti 1 > 1 = false.'),
        q('Hasil { ...{a: 1, b: 2}, ...{b: 9} }?', ['{a: 1, b: 9}', '{a: 1, b: 2}', '{b: 9}'], 0, 'Properti kanan menimpa.'),
        q('Hasil 2 ** 3 ** 2?', ['512', '64', '81'], 0, '** asosiatif kanan: 3 ** 2 = 9, lalu 2 ** 9.')],
    so=[SX('Gabungkan konfigurasi bawaan <code>{port: 3000, log: true, db: {host: "localhost"}}</code> dengan <code>{port: 8080}</code>, lalu ambil port dan host dengan destructuring bersarang.', '{...bawaan, ...custom}; db tetap dari bawaan.',
           "const bawaan = { port: 3000, log: true, db: { host: 'localhost' } };\nconst cfg = { ...bawaan, ...{ port: 8080 } };\nconst { port, db: { host } } = cfg;\nconsole.log(port, host, cfg.log);")]),
]),
]
